void w2w_dbg_print (Cmd_List cmd)
{
  #if DBG_W2W == 1
  
    dbg_tx_text("\r\nCmd = ") ;
    dbg_tx_h8(cmd) ;

    if( cmd & INPUT_ON)
      {
        dbg_tx_text(" ON") ;
      }
  #endif
}






